import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { isAdmin } from "./admin.js";
import { handleMessage, handleCallback } from "./handlers.js";
import { premium } from "./navigation.js";
import { SUPABASE_URL, db, secretCache, chatLanguages, secret, telegram, withPlan, finishUpdate } from "./runtime.js";
Deno.serve(async (request) => {
    const requestStarted=Date.now();
    let updateId=null,attempt=null,prepareMs=0,renderStarted=0,renderMs=0;
    try {
        if (request.method === "GET" || request.method === "HEAD") {
            const url = new URL(request.url);
            if (url.searchParams.get("asset") === "premium") {
                return fetch(`${SUPABASE_URL}/functions/v1/telegram-premium-image?v=20260903hd4`, { method: request.method });
            }
        }
        if (request.method !== "POST") {
            return new Response("method not allowed", { status: 405 });
        }
        let expectedSecret = await secret("telegram_webhook_secret");
        const suppliedSecret = request.headers.get("x-telegram-bot-api-secret-token") || "";
        if (suppliedSecret !== expectedSecret) {
            secretCache.delete("telegram_webhook_secret");
            expectedSecret = await secret("telegram_webhook_secret", true);
            if (suppliedSecret !== expectedSecret) {
                return new Response("unauthorized", { status: 401 });
            }
        }
        const payload = await request.json().catch(() => ({}));
        const from = payload.callback_query?.from || payload.message?.from;
        const chatId = payload.callback_query?.message?.chat?.id || payload.message?.chat?.id;
        if (!from?.id || !chatId)
            return Response.json({ ok: true, ignored: true });
        const prepareStarted=Date.now();
        const {data:prepared,error:claimError}=await db.rpc('prepare_telegram_update',{p_payload:payload});
        prepareMs=Date.now()-prepareStarted;
        const claim=prepared?.claim;
        if(claimError) throw claimError;
        if(claim===0) return Response.json({ok:true,duplicate:true});
        if(claim<0) return Response.json({ok:false,busy:true,retry_after_ms:50},{status:503,headers:{"retry-after":"0"}});
        updateId=payload.update_id;attempt=claim;
        const user = await withPlan({...prepared.user, __is_new_user:prepared.is_new_user === true}, prepared.subscription ?? null);
        user.request_update_id=updateId;
        user.request_attempt=attempt;
        user.__callback_acked=request.headers.get("x-callback-acked")==="1";
        if (!user.is_active && !isAdmin(user)) {
            await finishUpdate(updateId,attempt,true,null,{prepare_ms:prepareMs,total_ms:Date.now()-requestStarted});
            return Response.json({ ok: true, blocked: true });
        }
        chatLanguages.set(Number(chatId), String(user.ui_language || "de"));
        renderStarted=Date.now();
        if (payload.callback_query) {
            await handleCallback(payload.callback_query, user);
        }
        else if (payload.message?.chat?.type === "private" &&
            (payload.message?.text || payload.message?.document || payload.message?.photo)) {
            await handleMessage(payload.message, user);
        }
        renderMs=Date.now()-renderStarted;
        await finishUpdate(updateId,attempt,true,null,{prepare_ms:prepareMs,render_ms:renderMs,total_ms:Date.now()-requestStarted});
        return Response.json({ ok: true });
    }
    catch (error) {
        if(updateId!==null && attempt!==null) {
          try {if(renderStarted&&!renderMs)renderMs=Date.now()-renderStarted;await finishUpdate(updateId,attempt,false,String(error),{prepare_ms:prepareMs,render_ms:renderMs,total_ms:Date.now()-requestStarted});} catch(ackError){console.error('inbox_finish',String(ackError));}
        }
        console.error("telegram_command_runtime", error);
        return Response.json({ ok: false, error: "command_runtime_failed" }, { status: 500 });
    }
});

import { premium } from "./navigation.js";
import { purgePlatformSessions } from './platform-sessions.js';
import { profile } from "./profiles.js";
import { db, ADMIN_TELEGRAM_USER_IDS, esc, short, button, send, edit, telegram } from "./runtime.js";
export function isAdmin(user) {
    return ADMIN_TELEGRAM_USER_IDS.has(Number(user?.telegram_user_id));
}

export function effectivePremiumFor(user, subscription) {
    const now = Date.now();
    if (user?.plan_override === "free")
        return false;
    if (user?.plan_override === "premium" &&
        (!user.plan_override_expires_at ||
            new Date(user.plan_override_expires_at).getTime() > now))
        return true;
    if (user?.referral_bonus_until &&
        new Date(user.referral_bonus_until).getTime() > now)
        return true;
    return !!subscription &&
        ["active", "trialing"].includes(String(subscription.status || "")) &&
        (!subscription.current_period_end ||
            new Date(subscription.current_period_end).getTime() > now);
}

export function adminGrantLabel(grant) {
    return grant === "7d"
        ? "7 Tage"
        : grant === "30d"
            ? "30 Tage"
            : grant === "3m"
                ? "3 Monate"
                : "lebenslang";
}

export function adminGrantExpiry(grant) {
    if (grant === "free" || grant === "life")
        return null;
    const date = new Date();
    if (grant === "7d")
        date.setUTCDate(date.getUTCDate() + 7);
    else if (grant === "30d")
        date.setUTCDate(date.getUTCDate() + 30);
    else
        date.setUTCMonth(date.getUTCMonth() + 3);
    return date.toISOString();
}

export function adminOverrideLabel(user) {
    if (user.plan_override === "free")
        return "FREE";
    if (user.plan_override !== "premium")
        return "STRIPE";
    if (!user.plan_override_expires_at)
        return "PREMIUM · LEBENSLANG";
    const until = new Intl.DateTimeFormat("de-DE", {
        timeZone: "Europe/Berlin",
        dateStyle: "short",
        timeStyle: "short",
    }).format(new Date(user.plan_override_expires_at));
    return `PREMIUM · bis ${until}`;
}

export function adminPremiumNotice(grant) {
    return grant === "life"
        ? "💎 <b>Kostenloses Premium aktiviert</b>\n\nDu hast kostenlos Premium auf Lebenszeit bekommen. Premium ist ab sofort aktiv."
        : `💎 <b>Kostenloses Premium aktiviert</b>\n\nDu hast ${adminGrantLabel(grant)} kostenlos Premium bekommen. Premium ist ab sofort aktiv.`;
}

export async function adminUsers(user, chatId, messageId) {
    if (!isAdmin(user))
        return;
    const { data: users, error } = await db
        .from("bot_users")
        .select("id,telegram_user_id,first_name,last_name,username,is_active,plan_override,plan_override_expires_at,referral_bonus_until,created_at")
        .order("created_at");
    if (error)
        throw error;
    const ids = (users || []).map((entry) => entry.id);
    let subscriptions = [];
    if (ids.length) {
        const { data, error: subscriptionError } = await db
            .from("user_subscriptions")
            .select("user_id,status,current_period_end")
            .in("user_id", ids);
        if (subscriptionError)
            throw subscriptionError;
        subscriptions = data || [];
    }
    const subscriptionByUser = new Map(subscriptions.map((entry) => [String(entry.user_id), entry]));
    const rows = (users || []).map((entry) => {
        const premium = effectivePremiumFor(entry, subscriptionByUser.get(String(entry.id)));
        const name = short([entry.first_name, entry.last_name].filter(Boolean).join(" ") ||
            entry.username ||
            String(entry.telegram_user_id), 34);
        return [
            button(`${entry.is_active ? (premium ? "💎" : "▫️") : "🚫"} ${name} · ${entry.is_active ? (premium ? "PREMIUM" : "FREE") : "GESPERRT"}`, `admin:user:${entry.id}`),
        ];
    });
    if (!rows.length)
        rows.push([button("Keine Nutzer", "noop")]);
    const blocked = (users || []).filter((entry) => !entry.is_active).length;
    const text = `🔒 <b>Admin</b>\n\nNutzer: ${users?.length || 0} · gesperrt: ${blocked}`;
    const markup = { inline_keyboard: rows };
    return messageId
        ? edit(chatId, messageId, text, markup)
        : send(chatId, text, markup);
}

export async function adminUser(user, chatId, messageId, userId) {
    if (!isAdmin(user))
        return;
    const { data: target, error } = await db
        .from("bot_users")
        .select("id,telegram_user_id,chat_id,first_name,last_name,username,is_active,plan_override,plan_override_expires_at,referral_bonus_until")
        .eq("id", userId)
        .maybeSingle();
    if (error)
        throw error;
    if (!target)
        return adminUsers(user, chatId, messageId);
    const { data: subscription, error: subscriptionError } = await db
        .from("user_subscriptions")
        .select("status,current_period_end,cancel_at_period_end")
        .eq("user_id", userId)
        .maybeSingle();
    if (subscriptionError)
        throw subscriptionError;
    const premium = effectivePremiumFor(target, subscription);
    const name = [target.first_name, target.last_name].filter(Boolean).join(" ") ||
        target.username || String(target.telegram_user_id);
    const text = `🔒 <b>Admin · Nutzer</b>\n\n` +
        `<b>${esc(name)}</b>\n` +
        `Telegram: <code>${esc(target.telegram_user_id)}</code>\n` +
        `Status: <b>${premium ? "PREMIUM" : "FREE"}</b>\n` +
        `Override: ${esc(adminOverrideLabel(target))}\n` +
        `Stripe: ${esc(String(subscription?.status || "inactive").toUpperCase())}\n` +
        `Zugriff: <b>${target.is_active ? "AKTIV" : "GESPERRT"}</b>`;
    const markup = {
        inline_keyboard: [
            [
                button("7 Tage", `admin:set:${userId}:7d`),
                button("30 Tage", `admin:set:${userId}:30d`),
            ],
            [
                button("3 Monate", `admin:set:${userId}:3m`),
                button("♾ Lebenslang", `admin:set:${userId}:life`),
            ],
            [button("Free setzen", `admin:set:${userId}:free`)],
            ...(isAdmin(target)
                ? [[button("🔒 Admin-Konto", "noop")]]
                : [
                    [button(target.is_active ? "🚫 Nutzer sperren" : "✅ Nutzer entsperren", target.is_active ? `admin:block:${userId}` : `admin:unblock:${userId}`)],
                    [button("🗑 Nutzer löschen", `admin:delete:${userId}`)],
                ]),
            [button("← Nutzer", "admin:list")],
        ],
    };
    return edit(chatId, messageId, text, markup);
}

export async function setUserBlocked(userId, blocked) {
    const { data: target, error: targetError } = await db
        .from("bot_users")
        .select("id,telegram_user_id,is_active")
        .eq("id", userId)
        .maybeSingle();
    if (targetError)
        throw targetError;
    if (!target)
        throw new Error("user unavailable");
    if (isAdmin(target))
        throw new Error("admin accounts cannot be blocked");
    const { error } = await db
        .from("bot_users")
        .update({ is_active: !blocked, updated_at: new Date().toISOString() })
        .eq("id", userId);
    if (error)
        throw error;
    if (blocked) {
        const { error: profileError } = await db
            .from("search_profiles")
            .update({ is_active: false, updated_at: new Date().toISOString() })
            .eq("user_id", userId);
        if (profileError)
            throw profileError;
    }
}

export async function deleteUser(userId) {
    const { data: target, error: targetError } = await db
        .from("bot_users")
        .select("id,telegram_user_id")
        .eq("id", userId)
        .maybeSingle();
    if (targetError)
        throw targetError;
    if (!target)
        return;
    if (isAdmin(target))
        throw new Error("admin accounts cannot be deleted");
    await purgePlatformSessions(userId);
    const { error } = await db.from("bot_users").delete().eq("id", userId);
    if (error)
        throw error;
}

export async function setPlanOverride(userId, grant) {
    const plan = grant === "free" ? "free" : "premium";
    const expiresAt = adminGrantExpiry(grant);
    const { data: target, error } = await db
        .from("bot_users")
        .update({
        plan_override: plan,
        plan_override_expires_at: expiresAt,
        updated_at: new Date().toISOString(),
    })
        .eq("id", userId)
        .select("id,chat_id")
        .maybeSingle();
    if (error)
        throw error;
    if (!target)
        throw new Error("user unavailable");
    if (plan === "premium") {
        const { data: profiles, error: profileError } = await db
            .from("search_profiles")
            .select("id")
            .eq("user_id", userId);
        if (profileError)
            throw profileError;
        const profileIds = (profiles || []).map((profile) => profile.id);
        if (profileIds.length) {
            const { error: deliveryError } = await db
                .from("delivery_events")
                .update({ next_retry_at: null })
                .in("profile_id", profileIds)
                .eq("status", "pending");
            if (deliveryError)
                throw deliveryError;
        }
    }
    return target;
}


export const ANNOUNCEMENT_PROMPT = "📢 Admin · Ankündigung";

export async function createAnnouncementDraft(user, chatId, body) {
    if (!isAdmin(user))
        return;
    const text = String(body || "").trim();
    if (!text)
        return send(chatId, "Die Ankündigung darf nicht leer sein.");
    if (text.length > 3500)
        return send(chatId, "Die Ankündigung darf maximal 3.500 Zeichen lang sein.");
    const { data: announcement, error } = await db
        .from("telegram_announcements")
        .insert({ created_by: user.id, body: text })
        .select("id,body")
        .single();
    if (error)
        throw error;
    return send(chatId, `📢 <b>Ankündigung · Vorschau</b>\n\n${esc(text)}\n\nEmpfänger: alle aktiven Bot-Nutzer (Free + Premium).`, {
        inline_keyboard: [
            [button("📢 Ankündigung senden", `admin:announcement-send:${announcement.id}`)],
            [button("Abbrechen", `admin:announcement-cancel:${announcement.id}`)],
        ],
    });
}

export async function cancelAnnouncement(user, chatId, messageId, announcementId) {
    if (!isAdmin(user))
        return;
    const { data, error } = await db
        .from("telegram_announcements")
        .update({ status: "cancelled" })
        .eq("id", announcementId)
        .eq("status", "draft")
        .select("id")
        .maybeSingle();
    if (error)
        throw error;
    return edit(chatId, messageId, data ? "Ankündigung abgebrochen." : "Diese Ankündigung wurde bereits verarbeitet.", {
        inline_keyboard: [[button("← Admin", "admin:list")]],
    });
}

export async function sendAnnouncement(user, chatId, messageId, announcementId) {
    if (!isAdmin(user))
        return;
    const { data: locked, error: lockError } = await db
        .from("telegram_announcements")
        .update({ status: "sending" })
        .eq("id", announcementId)
        .eq("status", "draft")
        .select("id,body")
        .maybeSingle();
    if (lockError)
        throw lockError;
    if (!locked) {
        return edit(chatId, messageId, "Diese Ankündigung wurde bereits verarbeitet.", {
            inline_keyboard: [[button("← Admin", "admin:list")]],
        });
    }

    const { data: recipients, error: recipientError } = await db
        .from("bot_users")
        .select("chat_id")
        .eq("is_active", true)
        .not("chat_id", "is", null);
    if (recipientError)
        throw recipientError;

    let sent = 0;
    let failed = 0;
    const rows = recipients || [];
    await db.from("telegram_announcements").update({ recipient_count: rows.length }).eq("id", announcementId);

    for (const recipient of rows) {
        try {
            await telegram("sendMessage", {
                chat_id: Number(recipient.chat_id),
                text: locked.body,
                link_preview_options: { is_disabled: true },
            });
            sent += 1;
        }
        catch (error) {
            failed += 1;
            console.error("announcement_delivery", Number(recipient.chat_id), String(error));
        }
        if (rows.length > 1)
            await new Promise(resolve => setTimeout(resolve, 45));
    }

    const status = failed === 0 ? "sent" : "partial";
    const { error: finishError } = await db
        .from("telegram_announcements")
        .update({
            status,
            sent_count: sent,
            failed_count: failed,
            sent_at: new Date().toISOString(),
        })
        .eq("id", announcementId);
    if (finishError)
        throw finishError;

    return edit(chatId, messageId, `📢 <b>Ankündigung versendet</b>\n\nEmpfänger: ${rows.length}\nErfolgreich: ${sent}\nFehlgeschlagen: ${failed}`, {
        inline_keyboard: [[button("← Admin", "admin:list")]],
    });
}

import { LANGS } from "./localization.js";
import { profile } from "./profiles.js";
import { db, PREMIUM_LINK, SAVED_PAGE_SIZE, short, button, send, edit, sendPremiumPreview, editPremiumPreview, hasCanceledPremium } from "./runtime.js";
export function homeKeyboard(user) {
    const rows = [
        [button("🔎 Suchprofil", "profile")],
        [button("👤 Bewerberprofil", "platforms:profile-new")],
        [button(user.is_premium ? "⚡ Auto-Bewerbung" : "🔒 Auto-Bewerbung", "platforms")],
        [button(hasCanceledPremium(user) ? "💎 Hol dir jetzt Premium mit 50 % Rabatt" : "💎 Premium testen", "premium")],
        [button("⚙️ Einstellungen", "settings")],
    ];
    return { inline_keyboard: rows };
}

export function home(user, chatId, messageId) {
    const text = "🏠 <b>Traumwohnung Hamburg</b>\n\n" +
        "Dein Bot, der rund um die Uhr passende Wohnungen sucht und dich automatisch bewirbt.\n\n" +
        "<b>In 3 Schritten zur automatisierten Bewerbung:</b>\n\n" +
        "1. Suchprofil erstellen\n" +
        "2. Bewerberprofil erstellen\n" +
        "3. Auto-Bewerbung einrichten\n\n" +
        "<b>Jetzt loslegen!👇</b>";
    return messageId
        ? edit(chatId, messageId, text, homeKeyboard(user))
        : send(chatId, text, homeKeyboard(user));
}

export async function premium(user, chatId, messageId, messageHasPhoto = false) {
    const rows = [];
    let text;
    const checkoutUrl = `${PREMIUM_LINK}?client_reference_id=${encodeURIComponent(user.id)}`;
    const discounted = hasCanceledPremium(user);
    if (user.is_premium) {
        text = "💎 <b>Traumwohnung Premium</b>\n\n✅ <b>Premium ist aktiv.</b>\n\n<b>Deine Vorteile:</b>\n⚡ Sofortige Zustellung\n🔎 Bis zu 4 Suchprofile\n🤖 Auto-Bewerbung\n🔓 Baugenossenschafts-Angebote öffnen\n⭐️ Inserate speichern";
        let portal = null;
        try {
            const result = await db.rpc("get_bot_secret", { secret_name: "stripe_portal_url" });
            if (!result.error)
                portal = result.data;
        }
        catch {
        }
        const billingUrl = typeof portal === "string" && /^https:\/\/billing\.stripe\.com\//.test(portal) ? portal : checkoutUrl;
        rows.push([{ text: "💳 Abo verwalten", url: billingUrl }]);
    }
    else {
        text = "💎 <b>Traumwohnung Premium</b>\n\n<b>Deine Vorteile:</b>\n⚡ Sofortige Zustellung\n🔎 Bis zu 4 Suchprofile\n🤖 Auto-Bewerbung\n🔓 Baugenossenschafts-Angebote öffnen\n⭐️ Inserate speichern\n\n" + "<s>1,99 €</s> <b>0,99 € / Monat</b>" + "\nKeine Mindestlaufzeit · jederzeit kündbar";
        rows.push([{ text: discounted ? "💎 Hol dir jetzt Premium mit 50 % Rabatt" : "💎 Premium testen", url: checkoutUrl }]);
    }
    rows.push([button("← Zurück", "home")]);
    const markup = { inline_keyboard: rows };
    return messageId
        ? edit(chatId, messageId, text, markup)
        : send(chatId, text, markup);
}

export async function saved(user, chatId, messageId, requestedPage = 0) {
    if (!user.is_premium)
        return premium(user, chatId, messageId);
    const { count, error: countError } = await db
        .from("saved_listings")
        .select("id", { count: "exact", head: true })
        .eq("user_id", user.id);
    if (countError)
        throw countError;
    const total = count || 0;
    if (!total) {
        const text = "⭐️ <b>Gespeicherte Inserate</b>\n\nNoch keine Inserate gespeichert.";
        const markup = { inline_keyboard: [[button("← Zurück", "home")]] };
        return messageId
            ? edit(chatId, messageId, text, markup)
            : send(chatId, text, markup);
    }
    const pages = Math.max(1, Math.ceil(total / SAVED_PAGE_SIZE));
    const page = Math.max(0, Math.min(Number(requestedPage) || 0, pages - 1));
    const from = page * SAVED_PAGE_SIZE;
    const to = from + SAVED_PAGE_SIZE - 1;
    const { data, error } = await db
        .from("saved_listings")
        .select("listing_id,created_at,listings(title,canonical_url,is_active)")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false })
        .range(from, to);
    if (error)
        throw error;
    const rows = [];
    for (const [index, row] of (data || []).entries()) {
        const listing = row.listings || {};
        const label = `🏠 ${from + index + 1}. ${short(listing.title, 42)}`;
        try {
            const url = new URL(listing.canonical_url);
            if (["http:", "https:"].includes(url.protocol)) {
                rows.push([{ text: label, url: url.href }]);
                continue;
            }
        }
        catch {
        }
        rows.push([button(label, "noop")]);
    }
    rows.push([
        button("‹ Vorherige", `saved:${Math.max(0, page - 1)}`),
        button(`${page + 1}/${pages}`, "noop"),
        button("Nächste ›", `saved:${Math.min(pages - 1, page + 1)}`),
    ]);
    rows.push([button("← Start", "home")]);
    const text = `⭐️ <b>Gespeicherte Inserate</b>\n\n${total} · Seite ${page + 1}/${pages}`;
    const markup = { inline_keyboard: rows };
    return messageId
        ? edit(chatId, messageId, text, markup)
        : send(chatId, text, markup);
}

export async function setPaused(userId, paused, slot) {
    let query = db.from("search_profiles").update({ is_active: !paused, updated_at: new Date().toISOString() }).eq("user_id", userId);
    if (slot)
        query = query.eq("profile_slot", slot);
    const { error } = await query;
    if (error)
        throw error;
}

export async function toggleSave(user, listingId) {
  if (!user.is_premium) return null;
  const {data,error}=await db.rpc('toggle_saved_once',{p_update_id:user.request_update_id,p_user_id:user.id,p_listing_id:listingId});
  if(error) throw error;
  return data;
}

export async function referralPage(user, chatId, messageId) {
    let { data: code, error } = await db.from("referral_codes").select("code").eq("user_id", user.id).maybeSingle();
    if (error)
        throw error;
    if (!code) {
        const value = crypto.randomUUID().replace(/-/g, "").slice(0, 8).toUpperCase();
        const result = await db.from("referral_codes").insert({ user_id: user.id, code: value }).select("code").single();
        if (result.error)
            throw result.error;
        code = result.data;
    }
    const link = `https://t.me/traumwohnunghamburgbot?start=ref_${code.code}`;
    await send(chatId, "🎁 <b>30 Tage Premium für 0 €</b>\n\n" +
        "Empfehle Traumwohnung Hamburg weiter und ihr erhaltet beide Premium kostenlos 💎\n\n" +
        "Dein persönlicher Link:");
    return send(chatId, link, {
        inline_keyboard: [
            [button("← Einstellungen", "settings")],
        ],
    });
}

export async function languagePage(user, chatId, messageId) {
    const codes = ["de", "en", "ckb", "ku", "prs", "fa", "ru", "tr", "ar"];
    const rows = codes.map((code) => [button(`${user.ui_language === code ? "✅ " : ""}${LANGS[code]}`, `lang:${code}`)]);
    rows.push([button("← Einstellungen", "settings")]);
    const markup = { inline_keyboard: rows };
    const text = "🌐 <b>Sprachen</b>\n\nWähle deine Sprache. Das komplette Bot-Menü wird entsprechend angezeigt.";
    return messageId ? edit(chatId, messageId, text, markup) : send(chatId, text, markup);
}

export async function settings(user, chatId, messageId) {
    const text = "⚙️ <b>Einstellungen</b>\n\nGespeicherte Inserate, Sprache, Hilfe und Premium-Empfehlungen.";
    const markup = { inline_keyboard: [
            [button(user.is_premium ? "⭐ Gespeichert" : "🔒 ⭐ Gespeichert", "saved")],
            [button("🌐 Sprache", "language")],
            [button("❓ Hilfe", "help")],
            [button("🎁 30 Tage Premium kostenlos", "referral")],
            [button("← Start", "home")],
        ] };
    return messageId ? edit(chatId, messageId, text, markup) : send(chatId, text, markup);
}

