 const all=[type,kind,mode,title].filter(Boolean).join(' ');
 if(/tauschwohnung|wohnungstausch|swap/.test(all))return'message_swap';
 if(/haus|house|einfamilienhaus|reihenhaus/.test(type+' '+kind))return'message_house';
